.task-row input { flex: none; min-width: 0; width: 1.2rem; height: 1.2rem; }
.task-row span { overflow-wrap: anywhere; min-width: 0; }
[role="alert"] { color: #a51d24; }
@media (max-width: 600px) { main { margin: 1rem; padding: 1rem; } }

