content.text:
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const dbPath = process.env.DB_PATH || 'data/workboard.sqlite';
if (dbPath !== ':memory:') mkdirSync(dirname(resolve(dbPath)), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
db.exec(`PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project ON tasks(project_id, id)`);
const listTasks = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? ORDER BY id ASC');
const findTask = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const taskJson = (task) => ({ ...task, completed: Boolean(task.completed) });

async function readJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id ASC');
const findProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') return json(res, 200, { status: 'ok' });
    if (req.method === 'GET' && path === '/api/projects') return json(res, 200, listProjects.all());
    const taskRoute = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskRoute) {
      const [, projectId, taskId] = taskRoute;
      if (!findProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
      if (!taskId && req.method === 'GET') return json(res, 200, listTasks.all(projectId).map(taskJson));
      if (!taskId && req.method === 'POST') {
        const payload = await readJson(req);
        const title = typeof payload?.title === 'string' ? payload.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = createTask.run(projectId, title);
        return json(res, 201, taskJson(findTask.get(projectId, result.lastInsertRowid)));
      }
      if (taskId && req.method === 'PATCH') {
        if (!findTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
        const payload = await readJson(req);
        if (typeof payload?.completed !== 'boolean') return json(res, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(payload.completed), projectId, taskId);
        return json(res, 200, taskJson(findTask.get(projectId, taskId)));
      }
    }
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && match) {
      const project = findProject.get(match[1]);
      return project ? json(res, 200, project) : json(res, 404, { error: 'Project not found' });
    }
    if (req.method === 'POST' && path === '/api/projects') {
      const payload = await readJson(req);
      const name = typeof payload?.name === 'string' ? payload.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(res, 201, { id: Number(result.lastInsertRowid), name });
    }
    if (req.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
      if (asset) {
        res.writeHead(200, { 'Content-Type': asset[0], 'Cache-Control': 'no-cache' });
        return res.end(asset[1]);
      }
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    if (!res.headersSent) json(res, error.status || 500, { error: error.status ? error.message : 'Unable to process request' });
    else res.end();
  }
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

const app = document.querySelector('#app');

function element(tag, text) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to load projects');
  return data;
}

function alertBox() {
  const alert = element('p');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  return alert;
}

function showError(alert, error) {
  alert.textContent = error.message;
  alert.hidden = false;
}

async function renderTasks(projectId, alert) {
  const path = `/api/projects/${projectId}/tasks`;
  const form = element('form');
  const label = element('label', 'Task title');
  label.htmlFor = 'task-title';
  const input = element('input');
  input.id = 'task-title';
  input.type = 'text';
  const submit = element('button', 'Create task');
  submit.type = 'submit';
  submit.disabled = true;
  form.append(label, input, submit);
  const filterLabel = element('label', 'Task filter');
  filterLabel.htmlFor = 'task-filter';
  const filter = element('select');
  filter.id = 'task-filter';
  for (const name of ['All', 'Open', 'Completed']) {
    const option = element('option', name);
    option.value = name;
    filter.append(option);
  }
  const filters = element('div');
  filters.className = 'task-filters';
  filters.append(filterLabel, filter);
  const list = element('section');
  list.setAttribute('aria-label', 'Tasks');
  app.append(form, filters, list);
  let tasks = [];
  function drawTasks() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      const row = element('div');
      row.dataset.testid = 'task-row';
      row.className = 'task-row';
      const checkbox = element('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        alert.hidden = true;
        try {
          const saved = await request(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = saved.completed;
          drawTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(alert, error);
        } finally { checkbox.disabled = false; }
      });
      row.append(checkbox, element('span', task.title));
      list.append(row);
    }
  }
  filter.addEventListener('change', drawTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    const title = input.value.trim();
    if (!title) return showError(alert, new Error('Task title is required'));
    submit.disabled = true;
    try {
      tasks.push(await request(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      }));
      drawTasks();
      input.value = '';
      input.focus();
    } catch (error) { showError(alert, error); }
    finally { submit.disabled = false; }
  });
  tasks = await request(path);
  drawTasks();
  submit.disabled = false;
}

async function render() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  const alert = alertBox();
  if (match) {
    const back = element('button', 'Projects');
    back.type = 'button';
    back.addEventListener('click', () => location.assign('/'));
    app.append(back, alert);
    try {
      const project = await request(`/api/projects/${match[1]}`);
      app.prepend(element('h1', project.name));
      document.title = `${project.name} — Workboard`;
      await renderTasks(project.id, alert);
    } catch (error) { showError(alert, error); }
  } else {
    app.append(element('h1', 'Workboard'));
    const form = element('form');
    const label = element('label', 'Project name');
    label.htmlFor = 'project-name';
    const input = element('input');
    input.id = 'project-name';
    input.name = 'name';
    input.type = 'text';
    const submit = element('button', 'Create project');
    submit.type = 'submit';
    form.append(label, input, submit);
    const list = element('section');
    list.setAttribute('aria-label', 'Projects');
    app.append(form, alert, list);
    function appendProject(project) {
      const row = element('div');
      row.dataset.testid = 'project-row';
      row.className = 'project-row';
      const open = element('button', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => location.assign(`/projects/${project.id}`));
      row.append(element('span', project.name), open);
      list.append(row);
    }
    submit.disabled = true;
    try {
      (await request('/api/projects')).forEach(appendProject);
      submit.disabled = false;
    } catch (error) { showError(alert, error); }
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      alert.hidden = true;
      const name = input.value.trim();
      if (!name) {
        showError(alert, new Error('Project name is required'));
        return;
      }
      submit.disabled = true;
      try {
        appendProject(await request('/api/projects', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        }));
        input.value = '';
        input.focus();
      } catch (error) { showError(alert, error); }
      finally { submit.disabled = false; }
    });
  }
  app.setAttribute('aria-busy', 'false');
}

render();

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';

async function start(dbPath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: dbPath },
    stdio: ['ignore', 'pipe', 'inherit'],
  });
  let output = '';
  const url = await new Promise((resolve, reject) => {
    child.on('error', reject);
    child.on('exit', (code) => reject(new Error(`Server exited: ${code}`)));
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) resolve(`http://127.0.0.1:${match[1]}`);
    });
  });
  return {
    url,
    async stop() {
      const stopped = once(child, 'exit');
      child.kill('SIGTERM');
      await stopped;
    },
  };
}

test('tasks: validation, ownership, completion, and persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-'));
  const dbPath = join(directory, 'tasks.sqlite');
  let server;
  try {
    server = await start(dbPath);
    const api = (path, method = 'GET', body) => fetch(server.url + path, {
      method, headers: { 'Content-Type': 'application/json' },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
    const first = await (await api('/api/projects', 'POST', { name: 'First' })).json();
    const second = await (await api('/api/projects', 'POST', { name: 'Second' })).json();
    const path = `/api/projects/${first.id}/tasks`;
    const other = `/api/projects/${second.id}/tasks`;
    for (const title of ['', '  \t ']) {
      const response = await api(path, 'POST', { title });
      assert.equal(response.status, 400);
      assert.equal((await response.json()).error, 'Task title is required');
    }
    assert.deepEqual(await (await api(path)).json(), []);
    const task = await (await api(path, 'POST', { title: '  Build it  ' })).json();
    const next = await (await api(path, 'POST', { title: 'Ship it' })).json();
    assert.equal(task.title, 'Build it');
    assert.equal(task.completed, false);
    assert.deepEqual(await (await api(path)).json(), [task, next]);
    assert.deepEqual(await (await api(other)).json(), []);
    assert.equal((await api(`${other}/${task.id}`, 'PATCH', { completed: true })).status, 404);
    assert.equal((await api(`${path}/${task.id}`, 'PATCH', { completed: 'yes' })).status, 400);
    const completed = await (await api(`${path}/${task.id}`, 'PATCH', { completed: true })).json();
    assert.equal(completed.completed, true);
    await server.stop();
    server = await start(dbPath);
    assert.deepEqual(await (await api(path)).json(), [completed, next]);
    assert.equal((await api(`/projects/${first.id}`)).status, 200);
    const reopened = await (await api(`${path}/${task.id}`, 'PATCH', { completed: false })).json();
    assert.equal(reopened.completed, false);
    await server.stop();
    server = await start(dbPath);
    assert.deepEqual(await (await api(path)).json(), [reopened, next]);
    assert.deepEqual(await (await api(other)).json(), []);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('projects: validation, ordering, routes, and persistence across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const dbPath = join(directory, 'projects.sqlite');
  let server;
  try {
    server = await start(dbPath);
    const get = (path) => fetch(server.url + path);
    const create = (name) => fetch(server.url + '/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
    const health = await get('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    for (const name of ['', '  \t\n ']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.equal((await response.json()).error, 'Project name is required');
    }
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    const first = await (await create('  First project  ')).json();
    const second = await (await create('Second project')).json();
    assert.equal(first.name, 'First project');
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    assert.equal((await get(`/projects/${first.id}`)).status, 200);
    assert.match(await (await get('/')).text(), /<title>Workboard<\/title>/);
    assert.equal((await get('/app.js')).status, 200);
    await server.stop();
    server = await start(dbPath);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

